package app.noir.mobile;
import android.content.*;
import androidx.test.platform.app.InstrumentationRegistry;
import org.json.*;
import org.junit.Test;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.*;
import static org.junit.Assert.*;

public final class AuditPhoneTest {
 Context isolated(){Context real=InstrumentationRegistry.getInstrumentation().getTargetContext();File root=new File(real.getFilesDir(),"audit-phone-"+UUID.randomUUID());assertTrue(root.mkdirs());return new ContextWrapper(real){@Override public Context getApplicationContext(){return this;}@Override public File getFilesDir(){return root;}@Override public File getExternalFilesDir(String type){File f=new File(root,"external");f.mkdirs();return f;}};}
 JSONObject episode(int n,boolean available)throws Exception{return new JSONObject().put("id","e"+n).put("group","show:tt123").put("imdb","tt123").put("season",1).put("episode",n).put("available",available);}
 @Test public void nextEpisodePrecedesChoiceOfSource()throws Exception{JSONObject first=episode(1,false),second=episode(2,false),third=episode(3,true);assertEquals("e2",PlayerActivity.chronologicalNext(first,Arrays.asList(third,first,second),System.currentTimeMillis()).optString("id"));second.put("airsAt","2099-01-01T00:00:00Z");assertNull(PlayerActivity.chronologicalNext(first,Arrays.asList(third,second),System.currentTimeMillis()));}
 @Test public void stalledFallbackAvoidsEquivalentBitrates()throws Exception{JSONArray all=new JSONArray().put(new JSONObject().put("url","https://example.test/equivalent").put("mbps",29)).put(new JSONObject().put("url","https://example.test/unknown")).put(new JSONObject().put("url","https://example.test/lighter").put("mbps",18));assertEquals(2,PlayerActivity.fallbackIndex(all,true,30));assertEquals(0,PlayerActivity.fallbackIndex(all,false,30));assertEquals(0,PlayerActivity.fallbackIndex(all,true,0));}
 @Test public void fallbackRetainsReleaseMetadata()throws Exception{JSONObject c=PhoneStream.tvCandidate(new JSONObject().put("name","Show.1080p.x264").put("size",1000000000L).put("resolution","1080p").put("hash","same-release").put("url","https://example.test/a"),1000);assertEquals(8,c.optDouble("mbps"),.001);assertEquals(1000000000L,c.optLong("size"));assertEquals("same-release",c.optString("hash"));}
 @Test public void unreadableQueueIsPreservedAndBlocksReplacement()throws Exception{Context c=isolated();File file=new File(c.getFilesDir(),"downloads.json");byte[] original="[broken queue".getBytes(StandardCharsets.UTF_8);Files.write(file.toPath(),original);DownloadStore store=new DownloadStore(c);assertFalse(store.queueFailure.isEmpty());assertArrayEquals(original,Files.readAllBytes(file.toPath()));File[] backups=c.getFilesDir().listFiles((dir,name)->name.startsWith("downloads-unreadable-"));assertNotNull(backups);assertEquals(1,backups.length);assertArrayEquals(original,Files.readAllBytes(backups[0].toPath()));try{store.enqueue(episode(1,false));fail("Unreadable queue must stay protected");}catch(IllegalStateException expected){}assertArrayEquals(original,Files.readAllBytes(file.toPath()));}
 @Test public void missingQueueStillStartsEmpty(){DownloadStore store=new DownloadStore(isolated());assertTrue(store.queueFailure.isEmpty());assertEquals(0,store.jobs().length());}
 @Test public void permanentFailuresKeepActionableCause(){assertTrue(DownloadStore.permanent(new IOException("Not enough phone storage")));assertTrue(DownloadStore.failureText(new IOException("ENOSPC")).contains("storage"));assertTrue(DownloadStore.permanent(PhoneDownloadProvider.sourceFailure(401)));assertTrue(DownloadStore.failureText(PhoneDownloadProvider.sourceFailure(401)).contains("key or subscription"));assertFalse(DownloadStore.permanent(new java.net.SocketTimeoutException()));assertFalse(DownloadStore.permanent(PhoneDownloadProvider.sourceFailure(503)));}
 @Test public void jobNeedsAnActualConsumer(){assertFalse(NoirApp.needsSync(false,false));assertTrue(NoirApp.needsSync(true,false));assertTrue(NoirApp.needsSync(false,true));}
 @Test public void cancellationStopsRequestLoops()throws Exception{DataStore.WorkCancel work=new DataStore.WorkCancel();DataStore.workCancel.set(work);try{work.cancel();assertTrue(DataStore.workStopped());try{DataStore.checkWork();fail("Stopped work must not continue");}catch(InterruptedIOException expected){}}finally{DataStore.workCancel.remove();}}
 @Test public void failedPersistenceNeverClaimsSaved(){DataStore data=new DataStore(isolated());data.writeFailure=new IllegalStateException("fixture");assertFalse(data.problemLine().isEmpty());assertEquals(data.problemLine(),data.localSaveStatus());}
 @Test public void pairingFailuresRemainVisible()throws Exception{Context c=isolated();Files.write(new File(c.getFilesDir(),"library.json").toPath(),"{\"token\":\"fixture\"}".getBytes(StandardCharsets.UTF_8));DataStore data=new DataStore(c);data.connection="Pairing expired or this phone was disconnected. Generate a new pairing link on the PC.";assertEquals(Loc.t("Pairing expired — pair again in Settings."),data.problemLine());data.connection="Connected · synced";assertEquals("",data.problemLine());}
 @Test public void batchRememberSavesOnceAndKeepsSnapshotsImmutable()throws Exception{DataStore data=new DataStore(isolated());JSONObject first=data.rememberPhoneItem(episode(1,false));JSONArray before=data.itemsShared();long version=data.version;List<JSONObject> added=data.rememberPhoneItems(Arrays.asList(episode(1,true),episode(2,false),episode(3,false),episode(2,true)));assertEquals(version+1,data.version);assertEquals(3,data.itemsShared().length());assertEquals(1,before.length());assertFalse(before.optJSONObject(0).optBoolean("available"));assertEquals("e2",added.get(3).optString("id"));added.get(1).put("title","changed by caller");assertFalse(data.item("e2").has("title"));long unchanged=data.version;data.rememberPhoneItems(Arrays.asList(episode(1,false),episode(2,false)));assertEquals(unchanged,data.version);data.flush();assertEquals(3,new DataStore(data.context).itemsShared().length());}
 @Test public void batchRememberMatchesCanonicalEpisodeWithoutChangingId()throws Exception{DataStore data=new DataStore(isolated());data.rememberPhoneItem(episode(1,false));JSONObject duplicate=episode(1,true).put("id","other-release-id");assertEquals("e1",data.rememberPhoneItems(Collections.singletonList(duplicate)).get(0).optString("id"));assertEquals(1,data.itemsShared().length());}
 @Test public void refreshingScheduleDoesNotMutateSharedItems()throws Exception{DataStore data=new DataStore(isolated());data.rememberPhoneItem(episode(1,false).put("airsAt","2026-01-01T00:00:00Z"));JSONArray before=data.itemsShared();data.refreshPhoneTitle(Collections.singletonList(episode(1,false).put("airsAt","2026-02-01T00:00:00Z")));assertEquals("2026-01-01T00:00:00Z",before.optJSONObject(0).optString("airsAt"));assertEquals("2026-02-01T00:00:00Z",data.item("e1").optString("airsAt"));}
 @Test public void trackChoicesAreScopedToReleaseAndPersist()throws Exception{DataStore data=new DataStore(isolated());data.trackPreference("e1","release-a","audio",PlayerPrefs.trackKey("English stereo",2),"en");data.trackPreference("e1","release-a","subtitle",PlayerPrefs.trackKey("English full",7),"en");data.trackPreference("e1","release-b","audio",PlayerPrefs.trackKey("Arabic",3),"ar");data.flush();DataStore restored=new DataStore(data.context);assertEquals("english stereo|2",restored.trackPreference("e1","release-a","audio").optString("track"));assertEquals("english full|7",restored.trackPreference("e1","release-a","subtitle").optString("track"));assertEquals("ar",restored.trackPreference("e1","release-b","audio").optString("language"));assertEquals(0,restored.trackPreference("e1","release-b","subtitle").length());assertEquals("en",PlayerPrefs.trackLanguage("Track 2 - English stereo"));assertEquals("ar",PlayerPrefs.trackLanguage("Arabic full"));assertEquals("fr",PlayerPrefs.trackLanguage("French commentary"));}
 @Test public void localThumbnailUsesBoundedCacheAndRejectsObsoleteWork()throws Exception{Context c=isolated();File file=new File(c.getFilesDir(),"poster.png");android.graphics.Bitmap original=android.graphics.Bitmap.createBitmap(96,144,android.graphics.Bitmap.Config.ARGB_8888);try(FileOutputStream out=new FileOutputStream(file)){assertTrue(original.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out));}assertNull(DiscoveryClient.localArt(file,48,()->false));android.graphics.Bitmap first=DiscoveryClient.localArt(file,48,()->true);assertNotNull(first);assertSame(first,DiscoveryClient.localArt(file,48,()->true));assertNotEquals(DiscoveryClient.localArtKey(file,48),DiscoveryClient.localArtKey(file,96));String key=DiscoveryClient.localArtKey(file,48);assertTrue(file.setLastModified(file.lastModified()+2000));assertNotEquals(key,DiscoveryClient.localArtKey(file,48));assertTrue(DiscoveryClient.bitmaps.size()<=DiscoveryClient.bitmaps.maxSize());}
 @Test public void deletingProfileReportsBytesAndStopsTransferBeforeCleanup()throws Exception{Context c=isolated();ProfileStore profiles=new ProfileStore(c);String id=profiles.create("Downloads fixture","#E4C084").optString("id");Context scoped=ProfileStore.context(c,id);File external=new File(scoped.getExternalFilesDir(null),"offline"),internal=new File(scoped.getFilesDir(),"offline");assertTrue(external.mkdirs());assertTrue(internal.mkdirs());File video=new File(external,"fixture.video"),part=new File(internal,"fixture.part"),untouched=new File(external,"keep.txt");Files.write(video.toPath(),new byte[11]);Files.write(part.toPath(),new byte[7]);Files.write(untouched.toPath(),new byte[3]);assertEquals(18,profiles.downloadBytes(id));try{profiles.delete(id);fail("Downloads need explicit deletion consent");}catch(IllegalArgumentException expected){}Files.write(new File(scoped.getFilesDir(),"downloads.json").toPath(),"[{\"id\":\"e1\",\"status\":\"paused\"}]".getBytes(StandardCharsets.UTF_8));DownloadStore store=new DownloadStore(scoped);store.activeId="e1";boolean[] stopped={false};store.activeConnection=new java.net.HttpURLConnection(new java.net.URL("https://example.test/fixture")){public void disconnect(){stopped[0]=true;store.activeId="";}public boolean usingProxy(){return false;}public void connect(){}};synchronized(NoirApp.class){NoirApp.downloadStores.put(id,new java.lang.ref.WeakReference<>(store));}profiles.delete(id,true);assertTrue(stopped[0]);assertFalse(video.exists());assertFalse(part.exists());assertTrue(untouched.exists());for(JSONObject profile:DataStore.objects(profiles.list()))assertNotEquals(id,profile.optString("id"));}
 @Test public void explicitLibraryRemovalWinsOverImplicitMembership()throws Exception{JSONObject removed=episode(1,false).put("libraryAt",100).put("inLibrary",false),legacy=episode(2,false).put("inLibrary",true);assertEquals(Boolean.FALSE,MainActivity.libraryChoice(Arrays.asList(removed,legacy)));legacy.put("libraryAt",200);assertEquals(Boolean.TRUE,MainActivity.libraryChoice(Arrays.asList(removed,legacy)));assertNull(MainActivity.libraryChoice(Collections.singletonList(episode(3,false).put("libraryAt",0))));}
}
